const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define points and date
  const point1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const point2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const date = '2021-02-04';

  // 2. Get Sentinel-2 imagery
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate('2021-02-01', '2021-02-07')  // 3-day window for cloud-free chance
    .filterBounds(ee.Geometry.Point([-79.134088, 43.253621]))  // Center between points
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

  // Check if collection is empty
  const count = collection.size().getInfo();
  if (count === 0) {
    print("No suitable Sentinel-2 images found");
    print("<answer>C1</answer>");
    return;
  }

  // Get least cloudy image
  const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Calculate NDVI
  const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // 4. Extract NDVI values at points
  const ndvi1 = ndvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1.buffer(100),  // 100m buffer for stability
    scale: 10,
    maxPixels: 1e9
  }).get('NDVI');

  const ndvi2 = ndvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2.buffer(100),
    scale: 10,
    maxPixels: 1e9
  }).get('NDVI');

  // 5. Get pixel counts to validate data
  const count1 = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1.buffer(100),
    scale: 10,
    maxPixels: 1e9
  }).get('NDVI');

  const count2 = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2.buffer(100),
    scale: 10,
    maxPixels: 1e9
  }).get('NDVI');

  // 6. Retrieve values
  const [val1, val2, cnt1, cnt2] = await Promise.all([
    ndvi1.getInfo(), ndvi2.getInfo(), count1.getInfo(), count2.getInfo()
  ]);

  print(`Point 1 NDVI: ${val1 !== null ? val1.toFixed(3) : 'No data'}, Pixels: ${cnt1}`);
  print(`Point 2 NDVI: ${val2 !== null ? val2.toFixed(3) : 'No data'}, Pixels: ${cnt2}`);
  print(`Images found: ${count}`);

  // 7. Validate and determine answer
  if (val1 === null || val2 === null || cnt1 === 0 || cnt2 === 0) {
    print("<answer>C2</answer>");
  } else if (isNaN(val1) || isNaN(val2) || val1 > 1 || val2 > 1 || val1 < -1 || val2 < -1) {
    print("<answer>C3</answer>");
  } else if (val1 > val2) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
